function devicectlPositionals(args) {
  const positionals = [];
  for (let i = 1; i < args.length; i++) {
    if (args[i] === '--json-output') {
      i++;
      continue;
    }
    if (args[i].startsWith('-')) continue;
    positionals.push(args[i]);
  }
  return positionals;
}
